#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

# Microsoft Entra setup for the Outlook one-way calendar mirror (issue #13,
# docs/agents/outlook-sync.md). Registers the app, mints a credential — a
# locally generated certificate keypair is preferred (#100): only the public
# certificate is shared, no secret ever crosses by mail; a client secret is
# the fallback — grants Calendars.ReadWrite with admin consent, verifies the
# registration with a direct token request plus a throwaway Graph event — the
# job routes sit behind Netlify visitor protection until deploy.md go-live
# item 1, so a hand-POST to /api/jobs proves nothing — then writes the
# OUTLOOK_* variables (mailbox, tenant, client id and one complete
# credential) to the chosen Netlify context (the sandbox pair on the develop
# branch deploy, the production pair at go-live) and offers the application
# access policy last.
#
# The OUTLOOK_* values never land in .env.local on purpose: a local value
# would let a hand-run mirror real bookings. Captured values persist to the
# untracked state file instead (ENV_FILE below), so a re-run pre-fills every
# ask — overwrite them when you switch to the production pair at go-live.
#
# Azure click paths written 2026-10-14 from the live portal. If a page looks
# different, look for the same words on it before assuming the value moved.

TOTAL_STAGES=7
# State file for re-runs: every captured value persists here, so each ask
# pre-fills and Enter keeps it. Untracked via the .gitignore .env* rule,
# chmod 600, and never read by npm run dev — the mirror stays inert locally.
ENV_FILE=".env.azure-outlook"
NETLIFY_SET=() # "KEY (context)" written to Netlify this run
GRAPH_VERIFIED="" # "yes" only when stage 5 created a throwaway event

GUID_RE='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'

# ask_guid KEY "Prompt": like ask, but re-prompts until the value is a GUID —
# both captured IDs are GUIDs and a typo here only surfaces as token failures
# after a whole deploy cycle.
ask_guid() {
  local key="$1" prompt="$2"
  ask "$key" "$prompt"
  until [[ "${!key:-}" =~ $GUID_RE ]]; do
    warn "that is not a GUID (expected 8-4-4-4-12 hex); paste it again"
    ask "$key" "$prompt"
  done
}

# ask_mailbox KEY "Prompt": like ask, but re-prompts until the value has an
# address shape (name@domain). The verification call and the Netlify write
# both depend on it.
ask_mailbox() {
  local key="$1" prompt="$2"
  ask "$key" "$prompt"
  until [[ "${!key:-}" =~ ^[^@[:space:]]+@[^@[:space:]]+$ ]]; do
    warn "that does not look like an address (name@domain); paste it again"
    ask "$key" "$prompt"
  done
}

# urlencode STRING: percent-encode everything but unreserved characters.
# Graph event ids carry '/' and '=' and must not go raw into a URL path.
urlencode() {
  local s="$1" out="" c i hex
  for ((i = 0; i < ${#s}; i++)); do
    c=${s:i:1}
    case "$c" in
    [a-zA-Z0-9.~_-]) out+="$c" ;;
    *) printf -v hex '%%%02X' "'$c" && out+="$hex" ;;
    esac
  done
  printf '%s' "$out"
}

# netlify_env_one KEY VALUE public|secret CONTEXT: writes one variable to one
# deploy context. Secret values are marked so the Netlify UI never shows them.
netlify_env_one() {
  local key="$1" value="$2" kind="$3" ctx="$4"
  if [[ -z "$value" ]]; then
    SKIPPED+=("$key on $ctx (captured value was empty)")
    warn "no value captured for $key; skipped"
    return
  fi
  local -a args=(env:set "$key" "$value" --context "$ctx" --force)
  [[ "$kind" == "secret" ]] && args+=(--secret)
  if netlify "${args[@]}" >/dev/null 2>&1; then
    NETLIFY_SET+=("$key ($ctx)")
    printf '  %s✓ set%s %s on %s\n' "$GREEN" "$RESET" "$key" "$ctx"
  else
    SKIPPED+=("$key on $ctx")
    warn "could not set $key on $ctx; by hand: netlify env:set $key <value> --context $ctx --force"
  fi
}

# save_state KEY VALUE: persist a captured value to the state file so the
# next run pre-fills it (Enter keeps). Private and untracked.
save_state() {
  write_env "$1" "$2"
  chmod 600 "$ENV_FILE" 2>/dev/null || true
}

banner "Outlook 365 one-way sync: Microsoft Azure setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites"
say "Two role gates and one local tool. Answer honestly; the wizard adapts."
if confirm "Global Administrator (or Privileged Role Administrator) in the target tenant, right now?"; then
  note "good: stage 4 (admin consent) can complete today."
else
  warn "stage 4 needs an admin. You can still register the app and capture"
  warn "values, but the sync stays off until consent is granted. Re-run then."
fi
if confirm "Does the tenant hold the mailbox you will point at (a mailbox hosted in the tenant — e.g. its admin user; production: booking@thesocialhouse.dk)?"; then
  :
else
  warn "Graph writes need that exact address. Create the mailbox before the"
  warn "verification stage; it cannot be renamed from here."
fi
if command -v netlify >/dev/null 2>&1; then
  if netlify status >/dev/null 2>&1; then
    note "netlify CLI: logged in, site linked."
  else
    warn "netlify CLI is not logged in or the repo is not linked: run"
    warn "netlify login (and netlify link if needed), then re-run stage 6."
  fi
else
  warn "netlify CLI missing (npm i -g netlify-cli). Azure stages still fine;"
  warn "stage 6 will be skipped and the values can be written later."
fi
pause "Prerequisites checked."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "App registration"
say "One Entra app registration provides the client-credentials OAuth the"
say "mirror uses. Register it in the tenant you are working in now: the"
say "sandbox tenant for testing, thesocialhouse.dk at go-live."
open_url "https://portal.azure.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade"
step "Sign in with an account in that tenant."
step "New registration:"
step "  · Name: the-social-house-booking-sync"
step "  · Supported account types: Accounts in this organizational directory only (Single tenant)"
step "  · Redirect URI: leave everything empty"
step "  · Register"
step "The new app's Overview page shows both IDs — copy them."
ask_guid OUTLOOK_TENANT_ID "Directory (tenant) ID:"
ask_guid OUTLOOK_CLIENT_ID "Application (client) ID:"
save_state OUTLOOK_TENANT_ID "$OUTLOOK_TENANT_ID"
save_state OUTLOOK_CLIENT_ID "$OUTLOOK_CLIENT_ID"
pause "Registration done."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Credential: certificate (preferred) or client secret"
say "Entra needs one credential for the client-credentials flow. The"
say "certificate is the safer pair: the keypair is generated on this machine,"
say "only the public certificate reaches the tenant admin, and nothing secret"
say "is ever exchanged by mail (#100)."
# State file values only pre-fill via ask; the cert pair is set here, so
# load it back for the keep-or-regenerate offer on re-runs.
OUTLOOK_CLIENT_CERT=$(_existing OUTLOOK_CLIENT_CERT || true)
OUTLOOK_CLIENT_CERT_KEY=$(_existing OUTLOOK_CLIENT_CERT_KEY || true)
if confirm "Generate a certificate keypair now? (recommended; N falls back to a client secret)"; then
  if ! command -v openssl >/dev/null 2>&1 || ! command -v node >/dev/null 2>&1; then
    SKIPPED+=("Certificate credential (openssl and node are both required)")
    warn "openssl or node missing; fall back to the client secret below."
  elif [[ -n "$OUTLOOK_CLIENT_CERT" ]] && confirm "A keypair from an earlier run is saved in the state file. Keep it?"; then
    note "Keeping the saved keypair and its uploaded certificate."
  else
    WORKDIR=$(mktemp -d)
    step "Generating a 2048-bit keypair (three-year validity) in $WORKDIR…"
    openssl req -x509 -newkey rsa:2048 -nodes -sha256 \
      -keyout "$WORKDIR/booking-sync.key.pem" \
      -out "$WORKDIR/booking-sync.cert.pem" \
      -days 1095 -subj "/CN=the-social-house-booking-sync" 2>/dev/null
    note "Private key: $WORKDIR/booking-sync.key.pem  — never leaves this machine"
    note "Public cert: $WORKDIR/booking-sync.cert.pem  — this one is shared"
    step "Upload the public certificate (portal → the app registration →"
    step "Certificates & secrets → Certificates tab → Upload certificate):"
    open_url "https://portal.azure.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade"
    pause "Certificate uploaded?"
    OUTLOOK_CLIENT_CERT=$(base64 < "$WORKDIR/booking-sync.cert.pem" | tr -d '\n')
    OUTLOOK_CLIENT_CERT_KEY=$(base64 < "$WORKDIR/booking-sync.key.pem" | tr -d '\n')
    note "Certificate expires: $(openssl x509 -enddate -noout -in "$WORKDIR/booking-sync.cert.pem" | cut -d= -f2)"
    note "— renew before then; the sync stops when it lapses (same discipline"
    note "as a client secret). The private key survives only in $ENV_FILE"
    note "(chmod 600): deleting that file means generating and re-uploading."
    save_state OUTLOOK_CLIENT_CERT "$OUTLOOK_CLIENT_CERT"
    save_state OUTLOOK_CLIENT_CERT_KEY "$OUTLOOK_CLIENT_CERT_KEY"
    rm -rf "$WORKDIR"
  fi
fi
if [[ -z "$OUTLOOK_CLIENT_CERT" ]]; then
  say "Client secret fallback: same app page, left menu: Certificates & secrets."
  step "Client secrets tab → New client secret."
  step "Description: booking sync. Expires: pick the longest your tenant allows"
  step "(up to 24 months) and note the date — the sync stops when it lapses."
  step "Copy the Value column NOW; it is shown once. (The Secret ID column is"
  step "not the secret.)"
  ask_secret OUTLOOK_CLIENT_SECRET "Client secret Value (hidden):"
  [[ -z "$OUTLOOK_CLIENT_SECRET" ]] && warn "empty: the sync stays off until a secret is set on Netlify."
  save_state OUTLOOK_CLIENT_SECRET "$OUTLOOK_CLIENT_SECRET"
fi
pause "Credential captured."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "API permission + admin consent"
say "Same app page, left menu: API permissions."
step "Add a permission → Microsoft Graph → APPLICATION permissions"
step "(the tab is easy to miss — Delegated does not work for client credentials)."
step "Search 'Calendar' → Calendars.ReadWrite → Add permissions."
step "Grant admin consent for <tenant> → Yes. Leave the page only when the"
step "status reads 'Granted for <tenant>' with a green check."
step "Optional tidy: remove the default User.Read (Delegated) permission —"
step "nothing uses it; client credentials never delegate."
pause "Consent granted (or scheduled with your admin)?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Verify: token + throwaway event, straight at Microsoft"
say "This proves registration, credential, permission type and admin consent"
say "in one pass, from this laptop. No deploy is involved: the job routes sit"
say "behind Netlify visitor protection until the go-live checklist turns it"
say "off (docs/agents/deploy.md), so a hand-POST to /api/jobs/* 401s and"
say "proves nothing."
ask_mailbox OUTLOOK_MAILBOX "Mailbox to verify against (a mailbox hosted in the target tenant, e.g. its admin user; production: booking@thesocialhouse.dk):"
save_state OUTLOOK_MAILBOX "$OUTLOOK_MAILBOX"
if [[ -n "$OUTLOOK_CLIENT_CERT" ]]; then
  step "Verifying the certificate credential: token + throwaway event via node…"
  if node scripts/outlook-cert-verify.mjs \
      "$OUTLOOK_CLIENT_CERT" "$OUTLOOK_CLIENT_CERT_KEY" \
      "$OUTLOOK_TENANT_ID" "$OUTLOOK_CLIENT_ID" "$OUTLOOK_MAILBOX"; then
    GRAPH_VERIFIED="yes"
  else
    SKIPPED+=("Direct Graph verification (certificate credential failed)")
    warn "invalid_client / AADSTS7000276 = certificate not uploaded (or the"
    warn "wrong keypair); 403 access_rights_missing = consent not granted."
  fi
elif ! command -v curl >/dev/null 2>&1; then
  SKIPPED+=("Direct Graph verification (no curl)")
  warn "curl missing — run the token and event calls by hand against"
  warn "login.microsoftonline.com/$OUTLOOK_TENANT_ID/oauth2/v2.0/token and"
  warn "graph.microsoft.com/v1.0/users/$OUTLOOK_MAILBOX/calendar/events."
else
  step "Requesting a client-credentials token…"
  TOKEN_JSON=$(printf '%s' "$OUTLOOK_CLIENT_SECRET" | curl -s --max-time 30 \
    -d grant_type=client_credentials \
    -d client_id="$OUTLOOK_CLIENT_ID" \
    --data-urlencode "scope=https://graph.microsoft.com/.default" \
    --data-urlencode "client_secret@-" \
    "https://login.microsoftonline.com/$OUTLOOK_TENANT_ID/oauth2/v2.0/token") || TOKEN_JSON=""
  TOKEN=$(printf '%s' "$TOKEN_JSON" | sed -n 's/.*"access_token":"\([^"]*\)".*/\1/p')
  if [[ -z "$TOKEN" ]]; then
    SKIPPED+=("Direct Graph verification (token request failed)")
    warn "no token. Microsoft said: $(printf '%.300s' "$TOKEN_JSON")"
    warn "invalid_client / AADSTS7000218 = wrong client ID or secret; re-check both."
  else
    printf '  %s✓ token acquired%s — registration, secret and tenant are good.\n' "$GREEN" "$RESET"
    step "Creating a throwaway event on ${OUTLOOK_MAILBOX}…"
    START=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
    END=$(date -u -d '+1 hour' +%Y-%m-%dT%H:%M:%S.000Z 2>/dev/null || date -u -v+1H +%Y-%m-%dT%H:%M:%S.000Z)
    CREATE_JSON=$(printf '{"subject":"Outlook sync smoke test — safe to delete","start":{"dateTime":"%s","timeZone":"UTC"},"end":{"dateTime":"%s","timeZone":"UTC"}}' "$START" "$END")
    CREATE_RESP=$(curl -s --max-time 30 -X POST \
      -H "Authorization: Bearer $TOKEN" \
      -H "Content-Type: application/json" \
      -d "$CREATE_JSON" \
      "https://graph.microsoft.com/v1.0/users/$OUTLOOK_MAILBOX/calendar/events") || CREATE_RESP=""
    EVENT_ID=$(printf '%s' "$CREATE_RESP" | sed -n 's/.*"id":"\([^"]*\)".*/\1/p')
    if [[ -z "$EVENT_ID" ]]; then
      SKIPPED+=("Direct Graph verification (event create failed)")
      warn "create failed. Graph said: $(printf '%.300s' "$CREATE_RESP")"
      warn "403 access_rights_missing = admin consent not granted;"
      warn "403 ErrorAccessDenied = an application access policy excludes this mailbox;"
      warn "404 = the mailbox does not exist in this tenant."
    else
      GRAPH_VERIFIED="yes"
      printf '  %s✓ event created%s — consent and Calendars.ReadWrite are good.\n' "$GREEN" "$RESET"
      step "Deleting the throwaway event…"
      DELETE_CODE=$(curl -s -o /dev/null -w '%{http_code}' --max-time 30 -X DELETE \
        -H "Authorization: Bearer $TOKEN" \
        "https://graph.microsoft.com/v1.0/users/$OUTLOOK_MAILBOX/calendar/events/$(urlencode "$EVENT_ID")") || DELETE_CODE=""
      if [[ "$DELETE_CODE" == "204" || "$DELETE_CODE" == "404" ]]; then
        printf '  %s✓ deleted%s — nothing left behind in the calendar.\n' "$GREEN" "$RESET"
      else
        warn "delete answered '$DELETE_CODE' — remove 'Outlook sync smoke test' by hand."
      fi
    fi
  fi
fi
pause "Verification done."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Netlify: write the credential variables"
if [[ "$GRAPH_VERIFIED" != "yes" ]]; then
  say "Stage 5 did not prove the registration against Graph. At go-live a"
  say "pre-filled state file makes Enter-through easy — and easy to get wrong."
fi
if ! command -v netlify >/dev/null 2>&1 || ! netlify status >/dev/null 2>&1; then
  SKIPPED+=("Netlify env write (netlify CLI not logged in or site not linked)")
  warn "Skipping. Later: scripts/setup-netlify-env.sh stage 10, or re-run this wizard."
elif [[ "$GRAPH_VERIFIED" != "yes" ]] && ! confirm "Stage 5 verification did not pass — write these values to Netlify anyway?"; then
  SKIPPED+=("Netlify env write (stage 5 verification did not pass)")
  warn "Skipping the write. Re-run the wizard once stage 5 passes."
else
  say "One credential (certificate pair or client secret) and the mailbox go"
  say "to the Netlify site for the context(s) you pick. The mailbox is per"
  say "context by design: production mirrors"
  say "booking@thesocialhouse.dk, the develop branch deploy the sandbox one."
  ask NETLIFY_CONTEXTS "Context(s), comma-separated (production at go-live; branch-deploy for the sandbox pair) [production]:"
  [[ -z "$NETLIFY_CONTEXTS" ]] && NETLIFY_CONTEXTS="production"
  IFS=',' read -ra CTX <<< "$NETLIFY_CONTEXTS"
  for ctx in "${CTX[@]}"; do
    ctx="${ctx//[[:space:]]/}"
    [[ -z "$ctx" ]] && continue
    if [[ "$ctx" == "production" && "$OUTLOOK_MAILBOX" != "booking@thesocialhouse.dk" ]]; then
      warn "production should mirror booking@thesocialhouse.dk (Bilag 1 fixes it);"
      warn "you are about to write '$OUTLOOK_MAILBOX' there instead."
    fi
    if [[ "$OUTLOOK_MAILBOX" == "booking@thesocialhouse.dk" && "$ctx" != "production" ]]; then
      warn "the route refuses the Bilag-1 mailbox outside production — it would"
      warn "mirror this context's database into the staff calendar. Skipping."
      continue
    fi
    netlify_env_one OUTLOOK_TENANT_ID "$OUTLOOK_TENANT_ID" secret "$ctx"
    netlify_env_one OUTLOOK_CLIENT_ID "$OUTLOOK_CLIENT_ID" secret "$ctx"
    if [[ -n "$OUTLOOK_CLIENT_CERT" ]]; then
      netlify_env_one OUTLOOK_CLIENT_CERT "$OUTLOOK_CLIENT_CERT" secret "$ctx"
      netlify_env_one OUTLOOK_CLIENT_CERT_KEY "$OUTLOOK_CLIENT_CERT_KEY" secret "$ctx"
      note "A leftover OUTLOOK_CLIENT_SECRET on this context is ignored (the"
      note "certificate wins). Tidy it away with:"
      note "  netlify env:unset OUTLOOK_CLIENT_SECRET --context $ctx"
    else
      netlify_env_one OUTLOOK_CLIENT_SECRET "$OUTLOOK_CLIENT_SECRET" secret "$ctx"
    fi
    netlify_env_one OUTLOOK_MAILBOX "$OUTLOOK_MAILBOX" public "$ctx"
  done
  note "The context picks the values up on its next deploy; the job route only"
  note "answers once visitor protection is off (docs/agents/deploy.md go-live"
  note "item 1). End-to-end before any deploy, locally: copy these four"
  note "sandbox values into .env.local, run npm run dev, POST"
  note "/api/jobs/sync-calendar with JOB_SECRET — then empty them again so"
  note "local runs stay inert. Never copy the production pair locally."
fi
pause "Netlify write done (or skipped)."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Least privilege: application access policy (production go-live)"
say "Without a policy, Calendars.ReadWrite reaches every mailbox in the"
say "tenant. Microsoft's documented fix scopes the app to the booking"
say "mailbox only. Needs an Exchange admin with PowerShell 7."
if confirm "Apply the application access policy now? (production go-live only — after the sandbox validation passed)"; then
  open_url "https://learn.microsoft.com/en-us/graph/auth-limit-mailbox-access"
  step "Once: brew install --cask powershell, then run pwsh and paste —"
  say "  Install-Module ExchangeOnlineManagement -Scope CurrentUser"
  say "  Connect-ExchangeOnline   # Exchange admin account"
  say "  New-DistributionGroup -Name 'Graph booking sync' -Type Security \\"
  say "    -Members booking@thesocialhouse.dk"
  say "  # wait ~15 min for the new group to be usable everywhere, then:"
  say "  New-ApplicationAccessPolicy -AppId $OUTLOOK_CLIENT_ID \\"
  say "    -PolicyScopeGroupId 'Graph booking sync' -AccessRight RestrictAccess \\"
  say "    -Description 'Booking sync: shared booking mailbox only'"
  say "  Test-ApplicationAccessPolicy -Identity booking@thesocialhouse.dk \\"
  say "    -AppId $OUTLOOK_CLIENT_ID   # expect Allow for the booking mailbox"
  note "Afterwards the policy excludes the sandbox mailbox: any later sandbox"
  note "run answers 403 ErrorAccessDenied until that mailbox joins the scope"
  note "group or the policy is removed. That is the restriction working."
  note "Policy changes can take up to an hour to take effect — a first 403"
  note "right after applying it is not proof of a broken registration."
  pause "Policy applied (or not yet — Enter either way)."
else
  SKIPPED+=("Application access policy (re-run this wizard at production go-live)")
fi

# ── Done ──────────────────────────────────────────────────────────────────
finish
if (( ${#NETLIFY_SET[@]} )); then
  note "set ${#NETLIFY_SET[@]} Netlify variable(s):"
  for v in "${NETLIFY_SET[@]}"; do note "  - $v"; done
fi
note "Go-live, after deploy.md item 1 turns visitor protection off: deploy the"
note "production context, then force a run and watch the calendar:"
note "  curl -s -X POST https://<prod-url>/api/jobs/sync-calendar \\"
note "    -H 'Authorization: Bearer <JOB_SECRET from .env.local>'"
note "A 401 there is visitor protection, not a broken registration."
note "Credentials expire: the sync dies on the expiry date, client secret or"
note "certificate alike. Mint a replacement and re-run this wizard for"
note "production before it does — the certificate flow keeps the private key"
note "local and re-uploads only the public cert."
note "If you wrote branch-deploy for sandbox testing, clean up when done:"
note "  netlify env:unset OUTLOOK_TENANT_ID --context branch-deploy  (and CLIENT_ID, CLIENT_SECRET, MAILBOX)"
printf '\n'
